  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1120;
      --panel: rgba(15, 23, 42, 0.92);
      --panel-border: rgba(148, 163, 184, 0.18);
      --text: #e2e8f0;
      --muted: #94a3b8;
      --accent: #38bdf8;
      --accent-strong: #0ea5e9;
      --danger: #fda4af;
      --input-bg: rgba(15, 23, 42, 0.75);
      --shadow: 0 24px 80px rgba(2, 6, 23, 0.55);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 32px 16px;
      font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background:
        radial-gradient(circle at top, rgba(56, 189, 248, 0.15), transparent 32%),
        linear-gradient(160deg, #020617 0%, #0f172a 55%, #111827 100%);
      color: var(--text);
    }

    .support-card {
      width: min(100%, 560px);
      padding: 32px;
      border: 1px solid var(--panel-border);
      border-radius: 24px;
      background: var(--panel);
      backdrop-filter: blur(18px);
      box-shadow: var(--shadow);
    }

    .eyebrow {
      margin: 0 0 10px;
      color: var(--accent);
      text-transform: uppercase;
      letter-spacing: 0.12em;
      font-size: 0.78rem;
      font-weight: 700;
    }

    h1 {
      margin: 0 0 12px;
      font-size: clamp(2rem, 3vw, 2.4rem);
      line-height: 1.1;
    }

    .intro {
      margin: 0 0 28px;
      color: var(--muted);
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 18px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    label {
      font-weight: 600;
      font-size: 0.97rem;
    }

    input {
      width: 100%;
      border: 1px solid rgba(148, 163, 184, 0.22);
      border-radius: 14px;
      padding: 14px 16px;
      color: var(--text);
      background: var(--input-bg);
      font: inherit;
      transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
    }

    input::placeholder {
      color: #64748b;
    }

    input:focus {
      outline: none;
      border-color: rgba(56, 189, 248, 0.85);
      box-shadow: 0 0 0 4px rgba(56, 189, 248, 0.15);
      transform: translateY(-1px);
    }

    .helper-text,
    .error-text,
    .status-text {
      font-size: 0.9rem;
      line-height: 1.4;
    }

    .helper-text {
      color: var(--muted);
    }

    .error-text {
      min-height: 1.25em;
      color: var(--danger);
    }

    .form-field.invalid input {
      border-color: rgba(251, 113, 133, 0.8);
      box-shadow: 0 0 0 4px rgba(251, 113, 133, 0.12);
    }

    button {
      margin-top: 6px;
      border: 0;
      border-radius: 14px;
      padding: 14px 18px;
      font: inherit;
      font-weight: 700;
      color: #020617;
      background: linear-gradient(135deg, #7dd3fc 0%, #38bdf8 45%, #0ea5e9 100%);
      cursor: pointer;
      transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
      box-shadow: 0 14px 30px rgba(14, 165, 233, 0.25);
