<body>
  <main class="support-card">
    <p class="eyebrow">Support</p>
    <h1>Contact our support team</h1>
    <p class="intro">Send us your details and we will reach out as soon as possible to help with your request.</p>

    <form id="support-form" novalidate>
      <div class="form-field">
        <label for="full-name">Full name</label>
        <input
          id="full-name"
          name="fullName"
          type="text"
          autocomplete="name"
          placeholder="Jane Doe"
          required
        >
        <p class="error-text" id="full-name-error" aria-live="polite"></p>
      </div>

      <div class="form-field">
        <label for="email-address">Email address</label>
        <input
          id="email-address"
          name="email"
          type="email"
          autocomplete="email"
          placeholder="jane@example.com"
          required
        >
        <p class="error-text" id="email-address-error" aria-live="polite"></p>
      </div>

      <div class="form-field">
        <label for="phone-number">Phone number</label>
        <input
          id="phone-number"
          name="phone"
          type="tel"
          autocomplete="tel"
          inputmode="tel"
          placeholder="+1 555 123 4567"
        >
        <p class="helper-text" id="phone-number-helper">Optional. Use digits with spaces or dashes, for example +1 555 123 4567.</p>
        <p class="error-text" id="phone-number-error" aria-live="polite"></p>
      </div>

      <button type="submit">Submit request</button>
      <p class="status-text" id="form-status" aria-live="polite"></p>
    </form>
  </main>

  <script>
    const form = document.getElementById("support-form");
    const statusText = document.getElementById("form-status");

    const fields = [
      {
        input: document.getElementById("full-name"),
        error: document.getElementById("full-name-error"),
        validate(value) {
          return value.trim() ? "" : "Please enter your full name.";
        }
      },
      {
        input: document.getElementById("email-address"),
        error: document.getElementById("email-address-error"),
        validate(value) {
          if (!value.trim()) {
            return "Please enter your email address.";
          }

          return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())
            ? ""
            : "Please enter a valid email address.";
        }
      },
      {
        input: document.getElementById("phone-number"),
        error: document.getElementById("phone-number-error"),
        validate(value) {
          if (!value.trim()) {
            return "";
          }

          return /^[+]?[0-9()\-\s]{7,20}$/.test(value.trim())
            ? ""
            : "Use a valid phone number such as +1 555 123 4567.";
        }
      }
    ];

    function showError(field, message) {
      const wrapper = field.input.closest(".form-field");
      field.error.textContent = message;
      wrapper.classList.toggle("invalid", Boolean(message));
      field.input.setAttribute("aria-invalid", String(Boolean(message)));
    }

    function validateField(field) {
      const message = field.validate(field.input.value);
      showError(field, message);
      return !message;
    }

    fields.forEach((field) => {
      field.input.addEventListener("blur", () => {
        validateField(field);
      });

      field.input.addEventListener("input", () => {
        if (field.error.textContent) {
          validateField(field);
        }
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      statusText.textContent = "";

      const isValid = fields.every((field) => validateField(field));

      if (!isValid) {
        statusText.textContent = "Please fix the highlighted fields before submitting.";
        return;
      }

      statusText.textContent = "Your support request is ready to be sent.";
      form.reset();
      fields.forEach((field) => showError(field, ""));
    });
  </script>
